mapper.select:
SELECT pf.TENANT_ID AS tenantId, pf.PROD_CODE AS prodCode, p.PROD_NAME AS prodName, pf.FEATURE_ID AS featureId, pf.FEATURE_NAME AS featureName, pf.JOB_KINDS AS jobKinds FROM perm_prod_feature pf LEFT JOIN perm_prod p ON pf.PROD_CODE = p.PROD_CODE AND pf.TENANT_ID = p.TENANT_ID WHERE pf.TENANT_ID = #{tenantId}
AND (p.PROD_NAME LIKE CONCAT('%', #{keyword}, '%') OR pf.FEATURE_NAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY pf.PROD_CODE, pf.FEATURE_ID
